const express       = require("express");
const mongoose      = require("mongoose");
const morgan        = require("morgan");

const userRoute     = require("./routes/user.route");
const reportRoute   = require("./routes/report.route");
const roleRoute     = require("./routes/role.route");

mongoose.connect("mongodb://localhost:27017/userfeature");
const db = mongoose.connection;

db.once("open", () => {
  console.log("Database connection established!");
});

db.on("error", (err) => {
  console.log(err);
});

const app = express();
 
app.use(express.json());
app.use(morgan("dev"));
app.use('/pictures', express.static('pictures'));

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});

app.use("/api/user", userRoute);
app.use("/api/report", reportRoute);
app.use("/api/role", roleRoute);

const express = require('express');
const router = express.Router();
const roleController = require('../controllers/role.controller');

// Role management
router.post('/', roleController.createRole);
router.get('/', roleController.getRoles);
router.get('/user/:userId/permissions', roleController.getUserPermissions);
router.get('/:id', roleController.getRoleById);
router.put('/:id', roleController.updateRole);
router.delete('/:id', roleController.deleteRole);

// Role assignment (user-role link)
router.post('/assign', roleController.assignRoleToUser);
router.get('/assignments', roleController.listRoleUsers);
router.delete('/assignments/:id', roleController.removeRoleFromUser);

// Role access permissions
router.post('/access', roleController.createRoleAccess);
router.get('/access', roleController.getRoleAccesses);
router.get('/access/:id', roleController.getRoleAccessById);
router.put('/access/:id', roleController.updateRoleAccess);
router.delete('/access/:id', roleController.deleteRoleAccess);

// User effective permissions
router.get('/user/:userId/permissions', roleController.getUserPermissions);

module.exports = router;

const mongoose  = require("mongoose");
const Schema    = mongoose.Schema

const roleSchema = new Schema({
  name: {
    type: String,
    required: true,
    unique: true,
  },
  active: {
    type: String,
    enum: ["Y", "N"],
    default: "Y",
  },
});

const Role = mongoose.model("Role", roleSchema)
module.exports = Role

const mongoose  = require("mongoose");
const Schema    = mongoose.Schema

const roleUserSchema = new Schema({
  idroles: {
    type: mongoose.Schema.Types.ObjectId,
    ref: "Role",
    required: true,
  },
  idusers: {
    type: mongoose.Schema.Types.ObjectId,
    ref: "User",
    required: true,
  },
});

roleUserSchema.index({ idroles: 1, idusers: 1 }, { unique: true });

const RoleUser = mongoose.model("RoleUser", roleUserSchema)
module.exports = RoleUser

const mongoose  = require("mongoose");
const Schema    = mongoose.Schema

const roleAccessSchema = new Schema({
  idroles: {
    type: mongoose.Schema.Types.ObjectId,
    ref: "Role",
    required: true,
  },
  access: {
    type: String,
    required: true,
  },
  add: {
    type: Number,
    default: 0,
  },
  edit: {
    type: Number,
    default: 0,
  },
  delete: {
    type: Number,
    default: 0,
  },
}, {
  collection: "rolesaccess",
});

roleAccessSchema.index({ idroles: 1, access: 1 }, { unique: true });

const RoleAccess = mongoose.model("RoleAccess", roleAccessSchema)
module.exports = RoleAccess

